query DirectoryContact($id: ID!) {
  directoryContact(id: $id) {
    id
    firstName
    surname
    institutionName
    address
    countryCode
    phone
    email
    orcidId
    jobTitle
    profilePicture
    participants {
      id
      name
      type
      countryCode
      node {
        contacts(id: $id) {
          type
        }
      }
      people(id: $id) {
        role
        termStart
      }
    }
    roles {
      role
      term {
        start
        end
      }
    }
  }
}
